# python3 mkjobs.py 1|2 > jobsN.json : pass 1 = every scene's first state in both styles; pass 2 = the second state of each, edited from pass 1's image (same object, same framing)
import json,sys
ST={
 'ink':"Film noir comic book art drawn with a brush: heavy black brush ink, dry-brush texture, ink splatter, cross-hatching, rain streaks, deep solid blacks, like a drawn page by a master inker. The only colour is spot colour carrying the light: warm gold (#fdbc2a) where the light falls, with small accents of emerald green (#03c870) and signal red (#ff3a31); everything else black ink and cool greys. Drawn, not rendered: no smooth 3D surfaces, no photographic light, no realism. Nothing beige, nothing cream, nothing pastel.",
 'logo':"Flat vector graphic illustration in the style of a bold esports team badge: a solid near-black ground (#04070e), flat unshaded fills in exactly four colours, cream (#f8f0d9), gold (#fdbc2a), green (#03c870) and red (#ff3a31), hard ruled straight edges, every form leaning forward about twelve degrees like slanted italic speed lettering, parallel slanted speed slashes in green and red, thick hard-edged shapes. No gradients, no shading, no brush texture, no grain, no 3D, no realism, no outlines in other colours.",
}
TAIL=" Every blank plate, panel, frame, sign and poster is black or dark with a gold rim: no cream, white or pale surfaces. Absolutely no people: no figures, no faces, no hands, no silhouettes. Every sign, board, panel, card, ticket, slip, screen and plate is completely blank and empty: no text, no letters, no numbers, no digits, no logos, no symbols anywhere."
# scene: (aspect, first state, second state as an edit)
SC={
 'cover-p':('9:16',"A theatre box office booth at night seen straight on, filling the frame. Above the booth a tall marquee board of black glass with four wide empty horizontal letter tracks, ringed by round bulbs, facing the viewer flat; the top track widest. Below it the booth's arched window with a blank panel, and at the foot of the window a brass ticket slot from which one blank golden ticket pokes halfway out toward the viewer, catching the light. A wet street in front reflecting the lights.",None),
 'cover-l':('16:9',"A theatre box office booth at night seen straight on, centred, with dark street on both sides. Above the booth a wide marquee board of black glass with four wide empty horizontal letter tracks, ringed by round bulbs, facing the viewer flat. Below it the booth's arched window with a blank panel, and at the foot of the window a brass ticket slot from which one blank golden ticket pokes halfway out toward the viewer, catching the light. A wet street in front reflecting the lights.",None),
 'letter':('1:1',"Close-up of a sealed envelope lying flat and straight on, on a dark counter under one lamp: a black envelope with a gold border, its flap closed by a round gold wax seal; the envelope's face blank.",
           "Edit this exact image: the same envelope, same framing and light, now opened: the gold wax seal broken in two, the flap folded back, and a black card pulled two thirds out of the envelope toward the top, the card facing the viewer flat with a thin gold border and four empty horizontal ruled rows, all blank. Keep the style exactly."),
 'bell':('1:1',"A brass closing bell, like a stock exchange's, mounted on an iron wall bracket in the upper half of the frame, and below it a wide empty black slate board with a thin gold frame facing the viewer flat, taking the lower third.",
         "Edit this exact image: the same bell and board, same framing, but the bell is ringing: swung to one side with its clapper striking, bold sound-burst lines and motion arcs around it, the light on it brighter; the slate board below still completely blank. Keep the style exactly."),
 'ticket':('1:1',"Close-up of one golden ticket seen straight on and flat, filling most of the frame, slightly tilted, on black: scalloped edges, a perforated tear line near its right end making a stub, a fine engraved border, its face completely blank.",
           "Edit this exact image: the same ticket, same size and position, turned over to show its back: the back is black with a thin gold double frame, a wide empty gold name plate across its middle and two smaller empty panels under it, the stub on the right also black and empty. Keep the style exactly."),
 'vault':('1:1',"A massive round steel bank vault door seen straight on, shut tight, with a big spoked handle wheel and locking bolts around the rim, and a wide blank brass plate fixed on the door's face above the wheel, facing the viewer flat.",
          "Edit this exact image: the same vault door, same framing, now swung open a crack on its hinge: warm gold light pours out through the gap and falls across the floor, coins glinting inside; the blank brass plate still on the door's face, blank. Keep the style exactly."),
 'slip':('1:1',"A betting window seen straight on: a brass grille with vertical bars over a dark window, a polished counter in front, on the counter a blank paper betting slip in black with a gold border, beside it a heavy rubber stamp on its ink pad.",
         "Edit this exact image: the same window and counter, same framing, but the betting slip has been slid halfway under the grille, and a fresh round stamp impression in red ink sits on the slip as an empty double ring with nothing inside it; the rubber stamp lies beside the pad. Keep the style exactly."),
 'billboard':('1:1',"A box office wall of three tall poster frames side by side for coming attractions, brass frames with black glass, all three dark and blank, small bulbs around each frame unlit.",
              "Edit this exact image: the same three poster frames, same framing, but the first frame on the left is now lit from inside with warm gold light, its bulbs on, its glass still completely blank; the other two frames stay dark and unlit. Keep the style exactly."),
 'cinema':('16:9',"A pair of tall padded theatre doors with round porthole windows and brass push plates, closed, seen straight on in a dark lobby, a thin line of warm light under them.",
           "Edit this exact image: the same doors, same framing, now swung wide open inward onto a dark auditorium: a large blank cinema screen facing the viewer flat beyond the doors, glowing faintly, rows of empty seats in silhouette in front of it. Keep the style exactly."),
}
p=sys.argv[1];J=[]
for st,pre in ST.items():
  for k,(ar,a,b) in SC.items():
    if p=='1':J.append({'name':f'{k}-{st}','model':'gpt-image-2','input':{'prompt':pre+' '+a+TAIL,'aspect_ratio':ar,'resolution':'1K','quality':'medium','num_outputs':1}})
    elif b:J.append({'name':f'{k}-{st}-2','model':'gpt-image-2','refs':[f'img/{k}-{st}.jpg'],'input':{'prompt':b+' '+pre+TAIL,'aspect_ratio':ar,'resolution':'1K','quality':'medium','num_outputs':1}})
print(json.dumps(J,indent=1))
